"use strict";(self.webpackChunkchzhshch_blog=self.webpackChunkchzhshch_blog||[]).push([[20485],{28453:(e,n,o)=>{o.d(n,{R:()=>i,x:()=>r});var t=o(96540);const s={},a=t.createContext(s);function i(e){const n=t.useContext(a);return t.useMemo((function(){return"function"==typeof e?e(n):{...n,...e}}),[n,e])}function r(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(s):e.components||s:i(e.components),t.createElement(a.Provider,{value:n},e.children)}},61966:(e,n,o)=>{o.r(n),o.d(n,{assets:()=>l,contentTitle:()=>r,default:()=>g,frontMatter:()=>i,metadata:()=>t,toc:()=>h});const t=JSON.parse('{"id":"qiangguo/nosavehongkong","title":"","description":"This young lady\'s Cantonese is superb, and she loves Stephen Chow comedies. As for Hong Kong food and clothes, she is equally fond. But it still must be said: we absolutely must not do something as foolish as using mainland resources to rescue Hong Kong.","source":"@site/i18n/en/docusaurus-plugin-content-docs/current/qiangguo/nosavehongkong.md","sourceDirName":"qiangguo","slug":"/qiangguo/nosavehongkong","permalink":"/qiangguo/nosavehongkong","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"id":"nosavehongkong","title":"","hide_table_of_contents":true},"sidebar":"qiangguoSidebar","previous":{"title":"\u751f\u6b96\u5668\u3001\u4e0a\u5e1d\u3001\u795e\u4e0e\u5076\u50cf\uff0c\u8c08\u8c08\u4eba\u7c7b\u5d07\u62dc\u7684\u6a21\u5f0f","permalink":"/qiangguo/worshippattern"},"next":{"title":"\u628a\u56fd\u5bb6\u5efa\u7acb\u5728\u4e00\u5957\u795e\u5b66\u539f\u5219\u4e0a\u662f\u82cf\u8054\u5931\u8d25\u7684\u6839\u672c\u539f\u56e0","permalink":"/qiangguo/sovietunionfailreason"}}');var s=o(74848),a=o(28453);const i={id:"nosavehongkong",title:"",hide_table_of_contents:!0},r="We Absolutely Must Not Do Something as Foolish as Using Mainland Resources to Rescue Hong Kong",l={},h=[];function u(e){const n={h1:"h1",header:"header",p:"p",...(0,a.R)(),...e.components};return(0,s.jsxs)(s.Fragment,{children:[(0,s.jsx)(n.header,{children:(0,s.jsx)(n.h1,{id:"we-absolutely-must-not-do-something-as-foolish-as-using-mainland-resources-to-rescue-hong-kong",children:"We Absolutely Must Not Do Something as Foolish as Using Mainland Resources to Rescue Hong Kong"})}),"\n",(0,s.jsx)(n.p,{children:"This young lady's Cantonese is superb, and she loves Stephen Chow comedies. As for Hong Kong food and clothes, she is equally fond. But it still must be said: we absolutely must not do something as foolish as using mainland resources to rescue Hong Kong."}),"\n",(0,s.jsx)(n.p,{children:"The reason Hong Kong became Hong Kong is primarily due to the bravery of the people of Guangzhou. Everyone should know about the Sanyuanli anti-British resistance. Originally, the British wanted Guangzhou, but they were constantly hunted down there -- they couldn't even keep the tiny Shamian Island safe and had to cordon it off. In the end, they settled for Hong Kong just for some peace and quiet. Before the Cultural Revolution, Hong Kong was nothing compared to Guangzhou. The Cultural Revolution swapped their positions. If you have the chance to meet real Guangzhou people, they all know this, because virtually every Guangzhou native has relatives in Hong Kong, and how those relatives got there is an open secret."}),"\n",(0,s.jsx)(n.p,{children:"But Hong Kong's real prosperity came from certain systemic features of the mainland after reform -- anyone who has been in business knows exactly what I mean. However, because money came too easily, Hong Kong people developed bad habits. The British also played many dirty tricks before leaving, further complicating Hong Kong's problems. Yet the biggest issue remains Hong Kong people's mentality. In recent years, Guangzhou's aggressive development, especially the Grand Nansha strategy, has made Hong Kong people feel even more pressure. In the long run, the dragon head of the Pearl River Delta will certainly be Guangzhou -- culture, history, and geography all dictate this. But Hong Kong people still refuse to face this, unable to accept the reality that fortune shifts from east to west every thirty years, finding all manner of excuses, spending all day trying to leverage politics for economic advantage."}),"\n",(0,s.jsx)(n.p,{children:"Hong Kong's future has only one direction: integration into the Greater Pearl River Delta. Otherwise, it will ultimately be discarded by history. We absolutely must not do something as foolish as using mainland resources to rescue Hong Kong. The fundamental approach, standing on the perspective of historical economic development, is to help Hong Kong people understand sooner that integration is the only way out. Before economics, everything else is meaningless."}),"\n",(0,s.jsx)(n.p,{children:"Hong Kong need not be saved, nor can it be saved, because only Hong Kong people can save themselves. Saving themselves means swallowing their pride quickly and integrating into the strategic development of the Greater Pearl River Delta as soon as possible -- that is the bright road ahead. With so much time spent on marches and protests, why not work harder to find more business opportunities? Think about it: the Greater Pearl River Delta will connect South China, Central China, Southwest China, and Southeast Asia, inevitably becoming Asia's \"Tokyo Bay\" from a global economic perspective -- its status may even surpass Tokyo Bay's role in the Japanese economy. Instead of building this blueprint, is it really fun to quarrel all day? Where has your Cantonese culture's spirit of pragmatism gone? Have you eaten the British opium again?"}),"\n",(0,s.jsx)(n.p,{children:"Wake up, Hong Kong people. Otherwise, when the boat has sailed past Suzhou, there's no catching it -- and regrets will be useless then."})]})}function g(e={}){const{wrapper:n}={...(0,a.R)(),...e.components};return n?(0,s.jsx)(n,{...e,children:(0,s.jsx)(u,{...e})}):u(e)}}}]);